@Configuration
public class OpenApiConfig {

  @Bean
  public OpenAPI customOpenAPI() {
    return new OpenAPI()
      .info(new Info()
        .title("CICS GenApp Customer API")
        .version("1.0.0")
        .description("Customer management REST API"))
      .addSecurityItem(new SecurityRequirement().addList("bearer-jwt"))
      .components(new Components()
        .addSecuritySchemes("bearer-jwt", new SecurityScheme()
          .type(SecurityScheme.Type.HTTP)
          .scheme("bearer")
          .bearerFormat("JWT")
          .description("JWT token from Zitadel")));
  }
}

@Entity
@Table(name = "AUDIT_LOG")
public class AuditLog {
  @Id
  @GeneratedValue(strategy = GenerationType.UUID)
  private UUID auditId;

  private LocalDateTime timestamp;
  private String userId;

  @Enumerated(EnumType.STRING)
  private Operation operation; // CREATE, READ, UPDATE, DELETE

  private String entityType; // CUSTOMER
  private UUID entityId;

  @Column(columnDefinition = "jsonb") // PostgreSQL JSONB
  private String changes; // {field: {before, after}}

  private String ipAddress;
  private String userAgent;

  // Getters and setters
}

@RestController
@RequestMapping("/api/v1/audit")
@PreAuthorize("hasAnyRole('ADMIN', 'COMPLIANCE_OFFICER')")
public class AuditController {

  @GetMapping
  public ResponseEntity<PagedResponse<AuditLog>> queryAuditLogs(
    @RequestParam(required = false) String entity,
    @RequestParam(defaultValue = "100") int limit,
    @RequestParam(defaultValue = "0") int offset
  ) {
    PagedResponse<AuditLog> response = auditService.queryAuditLogs(entity, limit, offset);
    return ResponseEntity.ok(response);
  }
}
